        V[j].x = V[j + 1].x;
        V[j].y = V[j + 1].y;
        V[j].z = V[j + 1].z;
        side[j].x = side[j + 1].x;
        side[j].y = side[j + 1].y;
        side[j].z = side[j + 1].z;
