typedef struct vec { double x,y,z; } Vec;
void EnsureCounterClockWise(Vec *V);
void ComputeIntersection(Vec *P, Vec *Q, Vec *V, int *nv);
double Dot(Vec *a, Vec *b);
int Cross(Vec *a, Vec *b, Vec *c);
double Girard(int nv, Vec *V);
double computeOverlap(double *ilon, double *ilat, double *olon, double *olat, int energyMode, double refArea, double *areaRatio);

static void from_lonlat(double lonr, double latr, Vec *v){
  v->x=cos(latr)*cos(lonr); v->y=cos(latr)*sin(lonr); v->z=sin(latr);
}
static double OS_area(int nv, Vec *V){
  int i; double s=0; Vec cr;
  for(i=1;i<nv-1;i++){
    Cross(&V[i],&V[i+1],&cr);
    double numer=Dot(&V[0],&cr);
    double denom=1.+Dot(&V[0],&V[i])+Dot(&V[i],&V[i+1])+Dot(&V[i+1],&V[0]);
    s+=2.*fabs(atan2(numer,denom));
  }
  return s;
}
