  d=dot(axis,c); e1.x=axis.x-d*c.x;e1.y=axis.y-d*c.y;e1.z=axis.z-d*c.z; e1=norm(e1);
  e2=cross(c,e1);
  for(i=0;i<4;i++){
    d=dot(P[i],c); px[i]=dot(P[i],e1)/d; py[i]=dot(P[i],e2)/d;
    d=dot(Q[i],c); qx[i]=dot(Q[i],e1)/d; qy[i]=dot(Q[i],e2)/d;
  }
  ncn=shClip(4,px,py,4,qx,qy,ox,oy);
  if(ncn<3) return 0;
  for(k=0;k<ncn;k++){
    double r2=1.+ox[k]*ox[k]+oy[k]*oy[k], s=1./sqrt(r2);
    Vc[k].x=(ox[k]*e1.x+oy[k]*e2.x+c.x)*s;
    Vc[k].y=(ox[k]*e1.y+oy[k]*e2.y+c.y)*s;
    Vc[k].z=(ox[k]*e1.z+oy[k]*e2.z+c.z)*s;
  }
  return stableSolidAngle(ncn,Vc);
}

/* build a square pixel centered at (ra0,dec0) with side size (rad), axis-aligned */
static void makePixel(double ra0,double dec0,double size,double *lon,double *lat, double dra){
  double h=size/2;
  /* corners CCW; apply a small rotation dra (rad) to the pixel grid for generality */
  double ca=cos(dra),sa=sin(dra);
  double dx[4]={-h,h,h,-h}, dy[4]={-h,-h,h,h};
  int i;
  for(i=0;i<4;i++){
    double rx=ca*dx[i]-sa*dy[i], ry=sa*dx[i]+ca*dy[i];
    /* small-angle tangent plane approx to build sky corners */
    double dec=dec0+ry, ra=ra0+rx/cos(dec0);
    lon[i]=ra; lat[i]=dec;
  }
}

