    makePixel(ra0+0.3*s/cos(dec0),dec0+0.3*s,1.7*s,olon,olat,7.0*M_PI/180);
    double ov_sph=computeOverlap(ilon,ilat,olon,olat,0,1,&ar);
    for(int k=0;k<4;k++){P[k].x=cos(ilon[k])*cos(ilat[k]);P[k].y=sin(ilon[k])*cos(ilat[k]);P[k].z=sin(ilat[k]);
                         Q[k].x=cos(olon[k])*cos(olat[k]);Q[k].y=sin(olon[k])*cos(olat[k]);Q[k].z=sin(olat[k]);}
    double ov_tan=tangentOverlap(P,Q);
    /* self area compare */
    double self_s=computeOverlap(olon,olat,olon,olat,0,1,&ar);
    Vec Qs[4]; for(int k=0;k<4;k++)Qs[k]=Q[k];
    double self_t=tangentOverlap(Qs,Qs);
    double ratio = (ov_tan"'!=0&&ov_sph!=0)? ov_tan/ov_sph : (ov_tan==0&&ov_sph==0?1.0:NAN);
